/**
 * How the customer list is narrowed down. Understood by
 * {@link CustomerRepository}, which applies it to both the page query and the
 * count query, so that a filtered grid stays as lazy as an unfiltered one.
 *
 * <p>A customer matches when it satisfies <em>both</em> halves of the filter:
 *
 * <ul>
 * <li><b>name</b> — the text is split on whitespace into terms, and every term
 * must be a substring of the customer's first <em>or</em> last name. Case and
 * accents are ignored in both directions, so {@code makinen}, {@code MAKINEN}
 * and {@code mäkinen} all match {@code Mäkinen}. An empty text matches
 * everything.</li>
 * <li><b>status</b> — the customer's status must be one of the selected ones. An
 * empty selection matches everything.</li>
 * </ul>
 *
 * @param name     the name text as the user typed it, with surrounding and
 *                 repeated whitespace collapsed; never {@code null}
 * @param statuses the selected statuses, in declaration order; never
 *                 {@code null}, empty meaning "any status"
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    /** The filter that matches every customer. */
    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());

    public CustomerFilter {
        name = (name == null) ? "" : name.strip().replaceAll("\\s+", " ");
        statuses = (statuses == null || statuses.isEmpty())
                ? Set.of()
                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
    }

    public static CustomerFilter of(String name, Collection<CustomerStatus> statuses) {
        return new CustomerFilter(name, statuses == null ? Set.of() : Set.copyOf(statuses));
    }

    /** {@code true} when this filter matches every customer. */
    public boolean isEmpty() {
        return name.isEmpty() && statuses.isEmpty();
    }

    /** The name terms, normalized for matching; empty when no name is entered. */
    public List<String> nameTerms() {
        if (name.isEmpty()) {
            return List.of();
        }
        return List.of(normalize(name).split(" "));
    }

    /**
     * Compiles this filter once into a predicate, so that the name terms are
     * normalized once per query rather than once per row.
     */
    public Predicate<Customer> asPredicate() {
        if (isEmpty()) {
            return customer -> true;
        }
        List<String> terms = nameTerms();
        Set<CustomerStatus> selected = statuses;
        return customer -> matchesStatus(customer, selected) && matchesName(customer, terms);
    }

    private static boolean matchesStatus(Customer customer, Set<CustomerStatus> selected) {
        return selected.isEmpty() || selected.contains(customer.status());
    }

    private static boolean matchesName(Customer customer, List<String> terms) {
        if (terms.isEmpty()) {
            return true;
        }
        String firstName = normalize(customer.firstName());
        String lastName = normalize(customer.lastName());
        for (String term : terms) {
            if (!firstName.contains(term) && !lastName.contains(term)) {
                return false;
            }
        }
        return true;
    }

