import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Set;

import com.example.customers.domain.Customer;
import com.example.customers.domain.CustomerFilter;
import com.example.customers.domain.CustomerStatus;

import org.junit.jupiter.api.Test;

/** Unit tests for the matching rules, without any UI involved. */
class CustomerFilterTest {

    private static final Customer ADA =
            new Customer(1, "Ada", "Aaltonen", "ada@example.com", "Finland", CustomerStatus.ACTIVE);
    private static final Customer JARNO =
            new Customer(2, "Jarno", "Mäkinen", "jarno@example.com", "Netherlands", CustomerStatus.PENDING);
    private static final Customer JOSEPHINE =
            new Customer(3, "Joséphine", "Aaltonen", "jose@example.com", "Portugal", CustomerStatus.CLOSED);

    private static boolean matches(CustomerFilter filter, Customer customer) {
        return filter.asPredicate().test(customer);
    }

    private static CustomerFilter byName(String name) {
        return new CustomerFilter(name, Set.of());
    }

    @Test
    void emptyFilterMatchesEverything() {
        assertTrue(CustomerFilter.EMPTY.isEmpty());
        assertTrue(matches(CustomerFilter.EMPTY, ADA));
        assertTrue(matches(byName("   "), JARNO));
    }

    @Test
    void everyTermMustMatchFirstOrLastName() {
        assertTrue(matches(byName("ada aal"), ADA));
        assertTrue(matches(byName("aal ada"), ADA));
        assertTrue(matches(byName("  ada   aal  "), ADA));
        assertFalse(matches(byName("ada virtanen"), ADA));
    }

    @Test
    void matchingIgnoresCaseAndAccents() {
        assertTrue(matches(byName("makinen"), JARNO));
        assertTrue(matches(byName("MAKINEN"), JARNO));
        assertTrue(matches(byName("mäkinen"), JARNO));
        assertTrue(matches(byName("MÄKINEN"), JARNO));
        assertTrue(matches(byName("josephine"), JOSEPHINE));
        assertTrue(matches(byName("joséphine"), JOSEPHINE));
    }

    @Test
    void statusIsAndedWithTheName() {
        CustomerFilter active = new CustomerFilter("", Set.of(CustomerStatus.ACTIVE));
        assertTrue(matches(active, ADA));
        assertFalse(matches(active, JARNO));

        CustomerFilter activeOrClosed =
                new CustomerFilter("aaltonen", Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED));
        assertTrue(matches(activeOrClosed, ADA));
        assertTrue(matches(activeOrClosed, JOSEPHINE));
        assertFalse(matches(activeOrClosed, JARNO));
    }

    @Test
    void insignificantWhitespaceDoesNotChangeTheFilter() {
        assertEquals(byName("ada aal"), byName("  ada   aal "));
        assertEquals("ada aal", byName("  ada   aal ").name());
    }
}
