     * Puts the filter in the address bar. This replaces the current history entry
     * rather than pushing a new one, so narrowing the list does not fill the back
     * button with half-typed names.
     *
     * <p>The URL is built by hand rather than through {@link QueryParameters},
     * whose encoding would turn the comma between two statuses into
     * {@code %2C}.
     */
    private void writeFilterToUrl(CustomerFilter newFilter) {
        String url = urlFor(newFilter);
        getUI().ifPresent(ui -> replaceUrl(ui, url));
    }

    private String urlFor(CustomerFilter newFilter) {
        StringBuilder query = new StringBuilder();
        if (!newFilter.name().isEmpty()) {
            query.append(NAME_PARAMETER).append('=').append(encode(newFilter.name()));
        }
        if (!newFilter.statuses().isEmpty()) {
            if (!query.isEmpty()) {
                query.append('&');
            }
            query.append(STATUS_PARAMETER).append('=')
                    .append(newFilter.statuses().stream()
                            .sorted(Comparator.comparingInt(CustomerStatus::ordinal))
                            .map(CustomerStatus::name)
                            .collect(Collectors.joining(",")));
        }
        String url = query.isEmpty() ? routePath : routePath + "?" + query;
        // A relative URL of "" would mean "leave the address bar alone", which is
        // the one thing an emptied filter must not do; "." is the current
        // directory, and so drops the query string. This is what Flow's own
        // History does with an empty location.
        return url.isEmpty() ? "." : url;
    }

    private static void replaceUrl(UI ui, String url) {
        if (ui.getSession().getService().getDeploymentConfiguration().isReactEnabled()) {
            // Let the client-side router know, so its idea of the location stays
            // in step with the address bar. callback: false keeps it client-side.
            ui.getPage().executeJs("window.dispatchEvent(new CustomEvent('vaadin-navigate', "
                    + "{ detail: { state: null, url: $0, replace: true, callback: false } }))",
                    url);
        } else {
            ui.getPage().executeJs("window.history.replaceState(null, '', $0); "
                    + "window.dispatchEvent(new CustomEvent('vaadin-navigated'))", url);
        }
    }

    private static String encode(String value) {
        return URLEncoder.encode(value, StandardCharsets.UTF_8).replace("+", "%20");
